\begin{theorem}[Convergence guarantees]\label{thm:gen_conv_guarant}
		Without loss of generality, suppose $r_1<R$ and define the constants $\nu := \frac{R}{2(R-r_1)^2} $ and $\gamma:=\eta+3L\nu$. Fix a real $\bar{\rho} > \max\{\frac{2L}{r_1}, \gamma+\osa+3\accD L\}$ and a sequence $\beta_t > \max\{\frac{2L}{r_2},\gamma\}$. Let $\{x_t\}_{t=0}^T$ be the iterates generated by  Algorithm~\ref{alg:stoc_prox} and let  $t^*\in \{0,\ldots,T\}$ be sampled according to the discrete probability distribution
		$\mathbb{P}(t^*=t)\propto\frac{1}{\beta_t - \eta-\frac{3LR}{2(R-r_1)^2}}$.
		Then $x_{t^*}$ satisfies the estimate:	
		\begin{align*}
		\EE_t\left[\cC_{1/\bar \rho}(x_{t^\ast})^2\right] \leq \frac{2\bar\rho(f(x_0) - \min_{\cX} f) + \bar\rho^2L^2\sum_{t=0}^T a_t}{\sum_{t=0}^T \frac{\bar \rho - \gamma - \osa -  3\accD L}{\beta_t - \gamma }},
		\end{align*}
		where we define
		$$
		a_t :=  \frac{1}{\beta_t(\beta_t - \gamma)} + \frac{8\accR L(\bar \rho^{-1} + \beta_t^{-1})}{\beta_t^2} + \frac{4\accR ^2 L^2}{\beta_t^4}.
		$$
		In particular, if we set $\beta_t=\gamma+\frac{\sqrt{T+1}}{\alpha}$ for some positive  $\alpha < \frac{r_2}{2L-\gamma r_2}$, then it holds:
		\begin{align*}
		\EE_t\left[\cC_{1/\bar \rho}(x_{t^\ast})^2\right] \leq & \frac{2\bar\rho(f(x_0) - \min_{\cX} f)}{\alpha(\bar \rho - \gamma - \osa -  3\accD L)\sqrt{T+1}}\\
		&\quad+\frac{\alpha\bar \rho^2L^2}{\bar \rho - \gamma - \osa -  3\accD L}\left[\frac{1+\accR L(\bar \rho^{-1}+\frac{\alpha}{\sqrt{T+1}})}{\sqrt{T+1}}+\frac{4\alpha^2\accR ^2L^2}{(T+1)^{3/2}}\right].
		\end{align*}

	\end{theorem}

