\begin{lemma}[Proximally smooth sets]\label{lem_basic_prop_man}
	Consider an $R$-proximally smooth set $\cX$. The following are true.
	\begin{enumerate}
		\item {\bf (Lipschitz projector)} For any real $r\in (0, R)$ the estimate holds:
		$$\|\proj_{\cX}(x)-\proj_{\cX}(y)\|\le \frac{R}{R-r}\|x-y\|\qquad \forall x,y\in U_{\cX}(r).$$
		%		\item {\bf (Projections \& normals)} For any points $x\in\cX$, $y\in U_{\cX}(R)$, the equivalence holds:
		%		$$x=\proj_{\cX}(y)\qquad\Longleftrightarrow\qquad y-x\in N_{\cX}(x).$$ 
		\item\label{it3:lem} {\bf (Uniform normal inequality)} For any  point $x\in \cX$ and a normal $v\in N_{\cX}(x)$,  the inequality
		\begin{equation}\label{ineq:proximal_normal}
		\left\langle v,y-x\right\rangle\le \frac{\|v\|}{2R}\cdot \|y-x\|^2 \qquad\textrm{holds for all } y\in \cX.
		\end{equation}
	\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:prox_point_bound}
	Consider a function $g\colon \RR^d \to \RR$ that is $L$-Lipschitz continuous on a set $\cX\subseteq \RR^d$. Then for any point $x \in \cX$,  every point $\displaystyle \hat x \in \argmin_{y \in \cX} \left\{g(y) + \frac{\beta}{2} \|x - y\|^2\right\}$  satisfies the estimate $
	\|\beta(x - \hat x)\| \leq 2L.
	$
\end{lemma}

\begin{lemma}[One-step improvement]\label{lem:stoc_prox_descent}
		Fix an index $t$ and choose  $\hat x_t\in \cP_{1/\bar \rho}(x)$. Then the estimate holds:
		\begin{equation}
		\EE_t\left[\|\hat x_t - x_{t+1}\|^2\right] \leq  \frac{\beta +\osa+ 3\accD L - \bar \rho }{\beta- \gamma}\|x_t - {\hat x}_t \|^2 + L^2 a_t.\label{ineq:stoc_prox_descent}
		\end{equation}
		%	\end{align}
	\end{lemma}

\begin{proof}
		Since the statement of the theorem is independent of $x_0,\ldots, x_{t-1}$, we will simplify the notation by dropping the index $t$ in $x_t$, ${\tilde x}_t$, ${\hat x}_t$, $\xi_t$, $\EE_t$, $a_t$ and setting $x^+:=x_{t+1}$.
		By the definition of $\tilde x$, there exist vectors $v \in \partial f_{x}(\tilde x, \xi)$ and $w \in N_{\cX_{x}}(\tilde x)$ satisfying  $\beta(x - \tilde x) = v + w.$
		Using Lemma~\ref{lem:prox_point_bound} and Lipschitz continuity of $f_x(\cdot,\xi)$ yields the estimate $\|w\| \leq 3L$. Fix any  $y \in \cX\cap\BB(x,r_1)$. We then deduce
		\begin{align}
		\dotp{w, y- \tilde x} &= \dotp{w, (y - \proj_{\cX_x}(y))} + \dotp{w, \proj_{\cX_x}(y) - \tilde x}\notag\\
		&\leq \|w\|\cdot \dist(y, \cX_x) + \frac{\|w\|}{2R} \cdot\|\proj_{\cX_x}(y) - \tilde x\|^2\label{eqn:part2it1}\\
		&\leq \frac{\|w\|\accD}{2} \|y - x\|^2 + \frac{\|w\| \nu}{2} \|y - \tilde x\|^2,\label{eqn:part2it2}
		\end{align}
		where \eqref{eqn:part2it1} follows from the Cauchy-Schwarz inequality and from Lemma~\ref{lem_basic_prop_man}, while \eqref{eqn:part2it2} follows from (B4) and Lemma~\ref{lem_basic_prop_man}.
		Adding this estimate to the subgradient inequality for $f_x(\cdot,\xi)$ and completing the square, we conclude  for all $y \in \cX\cap\BB(x,r_1)$ the  bound:
		\begin{align}
		f_{x}(y, \xi) &\geq f_{x}(\tilde x, \xi) + \dotp{v + w, y- \tilde x} - \frac{\eta + \|w\| \nu}{2} \|y - \tilde x\|^2 - \frac{\|w\|\accD}{2}\|y - x\|^2\notag\\
		&\geq f_{x}(\tilde x, \xi) + \dotp{\beta(x - \tilde x) , y- \tilde x} - \frac{\eta + \|w\| \nu}{2} \|y - \tilde x\|^2  - \frac{\|w\|\accD}{2}\|y - x\|^2 \notag\\
		&= f_{x}(\tilde x, \xi) + \frac{\beta}{2}\left[ \|x - \tilde x\|^2 + \| y - \tilde x\|^2 - \|x - y\|^2\right]\label{eqn:perturb_three_point} \\
		&\qquad- \frac{\eta + \|w\| \nu}{2} \|y - \tilde x\|^2  - \frac{\|w\|\accD}{2}\|y - x\|^2.\notag
		\end{align}
		Lemma~\ref{lem:prox_point_bound} implies
		$
		\|\hat x - x\| \leq \frac{2L}{\bar \rho} \leq r_1.
		$
		Hence, setting $y = \hat x$ in \eqref{eqn:perturb_three_point} yields: 
		\begin{align}
		&\EE\left[\frac{\beta - \gamma}{2} \|\hat x - \tilde x\|^2 + \frac{\beta}{2}\| x - \tilde x\|^2 - \frac{\beta + \|w\|\accD }{2}\|x - \hat x\|^2\right]\notag\\
		&\leq \EE\left[f_x(\hat x, \xi) - f_x(\tilde x, \xi)\right]\notag \\
		&\leq \EE\left[f_x(\hat x, \xi) - f_x(x,\xi)\right]  + L \EE\left[\|x - \tilde x\|\right]\label{eqn:blah1}\\	
		&\leq f(\hat x) - f(x)  + L \EE\left[\|x - \tilde x\|\right] + \frac{\osa}{2}\|x - \hat x \|^2\label{eqn:blah2}\\
		&\leq \frac{\osa - \bar \rho }{2}\|x - \hat x \|^2 + L\sqrt{\EE\left[ \|x - \tilde x\|^2\right]},\label{eqn:blah3}
		%&\leq \frac{\tau - \bar \rho }{2}\|x - \hat x \|^2 + \frac{2L^2}{\beta}.
		\end{align}
		where \eqref{eqn:blah1} uses (B6), the estimate \eqref{eqn:blah2} uses (B2), and \eqref{eqn:blah3} uses the definition of $\hat x$ as the proximal point.
		Rearranging and setting $\delta :=\sqrt{ \EE\left[\|x - \tilde x\|^2\right]}$ yields the bound:
		\begin{equation}\label{eqn:intermed}
		\begin{aligned}
		\frac{\beta - \gamma}{2}\EE\left[\|\hat x - \tilde x\|^2\right] &\leq \frac{\beta + \accD\|w\|+ \osa - \bar \rho  }{2}\|x - \hat x \|^2 + L \delta - \frac{\beta }{2}\delta^2 \\
		&\leq \frac{\beta + \accD\|w\|+ \osa - \bar \rho  }{2}\|x - \hat x \|^2 + \frac{L^2}{2\beta},
		\end{aligned}
		\end{equation}
		where the last inequality follows by maximizing the expression  $L\delta - \frac{\beta }{2}\delta^2$ over $\delta\in \R$.
		To complete the proof, we will use the following estimate.
		\begin{claim}\label{claim1} The estimate holds:
			$
			\|\hat x -  x_+\|^2 \leq \|\hat x - \tilde x\|^2 + \frac{8\accR  L^3}{\beta^2}(\bar \rho^{-1} + \beta^{-1}) + \frac{4\accR ^2 L^4}{\beta^4}
			$.
		\end{claim}
		\begin{proof}
			Using Lemma~\ref{lem:prox_point_bound}, we deduce
			$\|\tilde x - x\| \leq 2L/\beta  \leq r_2$.
			In addition, we have $$\|\tilde x - x_+ \| = \|\tilde x - \cR_x(\tilde x)\| \leq \frac{\accR }{2}\|\tilde x - x\|^2\leq \frac{2\accR  L^2}{\beta^2}.$$ 
			Using the triangle inequality, we  deduce 
			$
			\|\hat x - x_+\|  \leq \|\hat x - \tilde x \| + \frac{2\accR  L^2}{\beta^2}.
			$
			Squaring both sides, we get
			$$
			\|\hat x - x_+\|^2  \leq \|\hat x - \tilde x \|^2 +  \frac{4\accR  L^2}{\beta^2}\|\hat x - \tilde x \| + \frac{4\accR ^2 L^4}{\beta^4}.
			$$
			Taking into account the estimate $
			\|\hat x - \tilde x \| \leq \|\hat x - x \| + \|x - \tilde x\| \leq 2L/\bar \rho + 2L/\beta,
			$
			completes the proof.
		\end{proof}
		Combining Claim~\ref{claim1} with the estimate \eqref{eqn:intermed}, we compute
		\begin{align*}
		\EE\left[\|\hat x -  x_+\|^2\right] &\leq \EE\left[\|\hat x - \tilde x\|^2\right] + \frac{8\accR  L^3(\bar \rho^{-1} + \beta^{-1})}{\beta^2} + \frac{4\accR ^2 L^4}{\beta^4} \\
		&\leq \frac{\beta + \accD\|w\|+ \osa - \bar \rho }{\beta- \gamma}\|x - \hat x \|^2 + L^2 a
		%\frac{L^2}{\beta(\beta - \gamma)} + \frac{8\accR  L^3(\bar \rho^{-1} + \beta^{-1})}{\beta^2} + \frac{4\accR ^2 L^4}{\beta^4}
		%	&=  \|x - \hat x \|^2  - \frac{\bar \rho - \gamma - \osa  -  \accD\|w\|}{\beta - \gamma}\|x - \hat x \|^2  + \frac{L^2}{\beta(\beta - \gamma)} + \frac{8\accR  L^3(\bar \rho^{-1} + \beta^{-1})}{\beta^2} + \frac{4\accR ^2 L^4}{\beta^4}.
		\end{align*}
		Bounding $\|w \| \leq 3L$ completes the proof of \eqref{ineq:stoc_prox_descent}.
	\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:gen_conv_guarant}]
		Fix an iteration $t$ and a  point  $\hat x_t\in\cP_{1/\bar \rho}(x_t)$. Then
		using the definition of the Moreau envelope and appealing to  Lemma~\ref{lem:stoc_prox_descent}, we deduce  
		\begin{align*}
		\EE_t[ \cM_{1/\bar \rho}(x_{t+1})] &\leq  \EE_t\left[f( \hat x_{t})  +\frac{\bar \rho}{2}\cdot \| x_{t+1} - \hat x_t \|^2\right],\\
		&\leq f( \hat x_{t}) +\frac{\bar \rho}{2}\left[\|\hat x_t-x_{t}\|^2+\left( \tfrac{\beta +\osa+ 3\accD L - \bar \rho }{\beta- \gamma}-1\right)\|\hat x_t-x_{t}\|^2  +L^2 a_t\right]\\
		&= \cM_{1/\bar \rho}(x_{t}) - \frac{\bar \rho- \gamma-\osa-3\accD L}{2\bar \rho(\beta_t-\gamma)}\cC_{1/\bar \rho}(x_t)^2  + \frac{\bar\rho L^2a_t}{2}.
		\end{align*}
		Taking expectations, iterating the inequality, and using the tower rule  yields:
		$$\sum_{t=0}^T \frac{\bar \rho - \gamma - \osa-3\accD L}{\beta_t-\gamma}\EE[\cC_{1/\bar{\rho}}(x_t)^2]\leq 2\bar{\rho}(\cM_{1/\bar \rho}(x_{0})-\min \cM_{1/\bar\rho})+  \bar \rho^2 L^2\cdot\sum_{t=0}^T a_t.$$
		Dividing through by $\sum_{t=0}^T \frac{\bar \rho - \gamma - \osa-3\accD L}{\beta_t-\gamma}$ and recognizing the left side as
		$\EE[\cC_{1/\bar{\rho}}(x_{t^*})^2]$ completes the proof.
	\end{proof}

