			$$
			\|y - \cR_x(y) \| \leq \frac{\accR }{2} \|x-y\|^2 \qquad \forall y \in \cX_x \cap \BB(x,r_2).
			$$
		\end{enumerate}
	}
\end{definition}

\begin{algorithm}[H]
		{\bf Input:} initialization $x_0\in \R^d$,   a sequence $\beta_t>0$,  and an iteration count $T\in \mathbb{N}$.
		\break{\bf Step } $t=0,\ldots,T$:	
		\begin{equation*}
		\begin{aligned}
		&\textrm{Sample } \xi_t \sim P\\
		& \textrm{Choose } \tilde x_{t} \in \argmin_{x \in \cX_x}~ \left\{f_{x_t}(x,\xi_t) + \frac{\beta_t}{2} \|x - x_t\|^2\right\}\\
		& \textrm{Set }  x_{t+1} = \cR_{x_t}(\tilde x_t)
		\end{aligned}
		\end{equation*}
		\caption{Retracted Stochastic Model Based Algorithm
			%: PSSM($x_0,T,\{\alpha_t\}$)
		}
		\label{alg:stoc_prox}
	\end{algorithm}

\begin{assumption}
		{\rm
			Fix a probability space $(\Omega,\mathcal{F},P)$ and equip $\R^d$ with the Borel $\sigma$-algebra. 
			We assume that there exist real $\eta,\osa, L, R, \accD, \accR, r_1, r_2 \in \R$ satisfying the following properties. 
			\begin{enumerate}
				\item[(B1)] {\bf (Sampling)} It is possible to generate i.i.d.\ realizations $\xi_1,\xi_2, \ldots \sim P$.
				\item[(B2)]\label{it:B2} {\bf (One-sided accuracy)} There is an open set $U$ containing $\cX $ and a measurable function $(x,y,\xi)\mapsto f_x(y,\xi)$, defined on $U\times U\times\Omega$, satisfying  $$\EE_{\xi}\left[f_x(x,\xi)\right]=f(x)
				\quad \textrm{and} 
				\quad\EE_{\xi}\left[f_x(y,\xi)-f(y)\right]
				\leq\frac{\osa}{2}\|y-x\|^2\qquad \forall x,y\in U.$$
				\item[(B3)] {\bf (Weak-convexity)} The function $f_x(\cdot,\xi)$ is $\eta$-weakly convex $\forall x\in U$, a.e. $\xi\sim P$.
				\item [(B4)] {\bf (Set approximation)} There exists a collection $\{(\cX_x,\cR_{x})\}_{x\in\cX}$ that is a set approximation of $\cX$ with parameters $(R,\accD,r_1,\accR ,r_2)$.
				\item[(B6)] {\bf (Lipschitz property)} $f$ is $L$-Lipschitz continuous on $\cX$; and for all $x\in \cX$ and a.e. $\xi\sim P$, the function $f_x(\cdot, \xi)$ is $L$-Lipschitz continuous on some neighborhood of $\cX_x$.
		\end{enumerate}}
	\end{assumption}

\begin{theorem}[Convergence guarantees]\label{thm:gen_conv_guarant}
		Without loss of generality, suppose $r_1<R$ and define the constants $\nu := \frac{R}{2(R-r_1)^2} $ and $\gamma:=\eta+3L\nu$. Fix a real $\bar{\rho} > \max\{\frac{2L}{r_1}, \gamma+\osa+3\accD L\}$ and a sequence $\beta_t > \max\{\frac{2L}{r_2},\gamma\}$. Let $\{x_t\}_{t=0}^T$ be the iterates generated by  Algorithm~\ref{alg:stoc_prox} and let  $t^*\in \{0,\ldots,T\}$ be sampled according to the discrete probability distribution
		$\mathbb{P}(t^*=t)\propto\frac{1}{\beta_t - \eta-\frac{3LR}{2(R-r_1)^2}}$.
		Then $x_{t^*}$ satisfies the estimate:	
		\begin{align*}
		\EE_t\left[\cC_{1/\bar \rho}(x_{t^\ast})^2\right] \leq \frac{2\bar\rho(f(x_0) - \min_{\cX} f) + \bar\rho^2L^2\sum_{t=0}^T a_t}{\sum_{t=0}^T \frac{\bar \rho - \gamma - \osa -  3\accD L}{\beta_t - \gamma }},
		\end{align*}
		where we define
		$$
		a_t :=  \frac{1}{\beta_t(\beta_t - \gamma)} + \frac{8\accR L(\bar \rho^{-1} + \beta_t^{-1})}{\beta_t^2} + \frac{4\accR ^2 L^2}{\beta_t^4}.
		$$
		In particular, if we set $\beta_t=\gamma+\frac{\sqrt{T+1}}{\alpha}$ for some positive  $\alpha < \frac{r_2}{2L-\gamma r_2}$, then it holds:
		\begin{align*}
		\EE_t\left[\cC_{1/\bar \rho}(x_{t^\ast})^2\right] \leq & \frac{2\bar\rho(f(x_0) - \min_{\cX} f)}{\alpha(\bar \rho - \gamma - \osa -  3\accD L)\sqrt{T+1}}\\
		&\quad+\frac{\alpha\bar \rho^2L^2}{\bar \rho - \gamma - \osa -  3\accD L}\left[\frac{1+\accR L(\bar \rho^{-1}+\frac{\alpha}{\sqrt{T+1}})}{\sqrt{T+1}}+\frac{4\alpha^2\accR ^2L^2}{(T+1)^{3/2}}\right].
		\end{align*}

	\end{theorem}

\begin{lemma}[One-step improvement]\label{lem:stoc_prox_descent}
		Fix an index $t$ and choose  $\hat x_t\in \cP_{1/\bar \rho}(x)$. Then the estimate holds:
		\begin{equation}
		\EE_t\left[\|\hat x_t - x_{t+1}\|^2\right] \leq  \frac{\beta +\osa+ 3\accD L - \bar \rho }{\beta- \gamma}\|x_t - {\hat x}_t \|^2 + L^2 a_t.\label{ineq:stoc_prox_descent}
		\end{equation}
		%	\end{align}
	\end{lemma}

\begin{align}
\dotp{w, y- \tilde x} &= \dotp{w, (y - \proj_{\cX_x}(y))} + \dotp{w, \proj_{\cX_x}(y) - \tilde x}\notag\\
&\leq \|w\|\cdot \dist(y, \cX_x) + \frac{\|w\|}{2R} \cdot\|\proj_{\cX_x}(y) - \tilde x\|^2\label{eqn:part2it1}\\
&\leq \frac{\|w\|\accD}{2} \|y - x\|^2 + \frac{\|w\| \nu}{2} \|y - \tilde x\|^2,\label{eqn:part2it2}
\end{align}
where \eqref{eqn:part2it1} follows from the Cauchy-Schwarz inequality and from Lemma~\ref{lem_basic_prop_man}, while \eqref{eqn:part2it2} follows from (B4) and Lemma~\ref{lem_basic_prop_man}.

Rearranging and setting $\delta :=\sqrt{ \EE\left[\|x - \tilde x\|^2\right]}$ yields the bound:
\begin{equation}\label{eqn:intermed}
\begin{aligned}
\frac{\beta - \gamma}{2}\EE\left[\|\hat x - \tilde x\|^2\right] &\leq \frac{\beta + \accD\|w\|+ \osa - \bar \rho  }{2}\|x - \hat x \|^2 + L \delta - \frac{\beta }{2}\delta^2 \\
&\leq \frac{\beta + \accD\|w\|+ \osa - \bar \rho  }{2}\|x - \hat x \|^2 + \frac{L^2}{2\beta},
\end{aligned}
\end{equation}
where the last inequality follows by maximizing the expression  $L\delta - \frac{\beta }{2}\delta^2$ over $\delta\in \R$.
To complete the proof, we will use the following estimate.

\begin{claim}\label{claim1} The estimate holds:
			$
